// begin marks a charge for the invoice as under way. It returns false when one already is.
func (s *Service) begin(orgID, invoiceID string) bool {
	s.mu.Lock()
	defer s.mu.Unlock()
	ref := invoiceRef{orgID, invoiceID}
	if s.inFlight[ref] {
		return false
	}
	if s.inFlight == nil {
		s.inFlight = map[invoiceRef]bool{}
	}
	s.inFlight[ref] = true
	return true
}

func (s *Service) end(orgID, invoiceID string) {
	s.mu.Lock()
	defer s.mu.Unlock()
	delete(s.inFlight, invoiceRef{orgID, invoiceID})
