		if err != nil {
			s.keepCharge(ref, c)
			return inv, store.Payment{}, err
		}
		c.payment, c.stored = p, true
	}
	inv, err := s.markPaid(ctx, inv, c.payment)
	if err != nil {
		s.keepCharge(ref, c)
		return inv, store.Payment{}, err
	}
	s.dropCharge(ref)
	return inv, c.payment, nil
}

// takenCharge returns the charge taken for the invoice whose payment is not stored yet, or nil.
func (s *Service) takenCharge(ref invoiceRef) *charged {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.taken[ref]
