	s.mu.Lock()
	defer s.mu.Unlock()
	if s.taken == nil {
		s.taken = map[invoiceRef]*charged{}
	}
	s.taken[ref] = c
}

func (s *Service) dropCharge(ref invoiceRef) {
	s.mu.Lock()
	defer s.mu.Unlock()
	delete(s.taken, ref)
}
