// settle stores the payment of a charge the gateway took and marks the invoice paid. If that fails, the charge is kept so
// that the next Pay for the invoice settles it rather than charging again.
func (s *Service) settle(ctx context.Context, ref invoiceRef, inv store.Invoice, c *charged) (store.Invoice, store.Payment, error) {
	if !c.stored {
		p, err := s.Store.CreatePayment(c.payment, s.Clock.Now())
		if err != nil {
			s.keepCharge(ref, c)
			return inv, store.Payment{}, err
		}
		c.payment, c.stored = p, true
	}
	inv, err := s.markPaid(ctx, inv, c.payment)
	if err != nil {
		s.keepCharge(ref, c)
		return inv, store.Payment{}, err
	}
	s.dropCharge(ref)
	return inv, c.payment, nil
}

// takenCharge returns the charge taken for the invoice whose payment is not stored yet, or nil.
func (s *Service) takenCharge(ref invoiceRef) *charged {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.taken[ref]
}

func (s *Service) keepCharge(ref invoiceRef, c *charged) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.taken == nil {
		s.taken = map[invoiceRef]*charged{}
	}
	s.taken[ref] = c
}

func (s *Service) dropCharge(ref invoiceRef) {
	s.mu.Lock()
	defer s.mu.Unlock()
	delete(s.taken, ref)
}

